fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len());
    let mut i = 0;

    // Loop invariant:
    // 0 <= i <= a.len()
    // result.len() == i
    // All elements in result so far are 1
    while i < a.len() {
        result.push(1);
        i += 1;
    }

    result
}